try:
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    name = ""
    try:
        name = str(data["name"] or "").strip()
    except (KeyError, TypeError):
        name = ""

    if not name:
        frappe.response["message"] = {"error": "name is required"}
    else:
        existing = frappe.db.get_value(
            "Incident Report", name, ["name", "nature_of_incident"], as_dict=True
        )
        if not existing:
            frappe.response["message"] = {"error": "Incident Report " + name + " not found"}
        elif existing.nature_of_incident != "Workplace Injury":
            frappe.response["message"] = {
                "error": name + " is not a Workplace Injury incident"
            }
        else:
            # Progressive case update — the follow-up screen sends only
            # whichever fields it changed. Each list below is only touched
            # when the client explicitly includes that key.
            check_fields = [
                "first_aid_given",
                "ambulance_needed",
                "taken_to_hospital",
                "police_report_required",
                "compensation_required",
                "wiba_claim_filed",
                "is_fatal",
                "doshs_reported",
            ]
            text_fields = [
                "injury_case_status",
                "injury_current_location",
                "first_aider_name",
                "ambulance_provider",
                "hospital_name",
                "hospital_admission_type",
                "attending_physician",
                "treatment_summary",
                "ob_number",
                "police_station",
                "wiba_claim_number",
                "payment_status",
                "activity_at_time_of_injury",
                "body_part_affected",
                "nature_of_injury",
                "doshs_reference_number",
            ]
            datetime_fields = ["ambulance_called_at"]
            date_fields = ["return_to_work_date", "doshs_reported_date"]

            updates = {}

            for key in check_fields:
                try:
                    v = data[key]
                    updates[key] = 1 if v else 0
                except (KeyError, TypeError):
                    pass

            for key in text_fields:
                try:
                    v = data[key]
                    updates[key] = str(v).strip() if v is not None else ""
                except (KeyError, TypeError):
                    pass

            for key in datetime_fields + date_fields:
                try:
                    v = data[key]
                    updates[key] = v if v else None
                except (KeyError, TypeError):
                    pass

            try:
                v = data["days_off_work"]
                if v in (None, ""):
                    updates["days_off_work"] = None
                else:
                    updates["days_off_work"] = int(v)
            except (KeyError, TypeError, ValueError):
                pass

            try:
                v = data["amount_paid"]
                if v in (None, ""):
                    updates["amount_paid"] = None
                else:
                    updates["amount_paid"] = float(v)
            except (KeyError, TypeError, ValueError):
                pass

            if not updates:
                frappe.response["message"] = {"error": "No updatable fields were sent"}
            else:
                # Closing a case without a resolution on the parent Incident
                # Report would leave it permanently "Open" — mirror the
                # status across so the general incident list reflects it too.
                closing = False
                try:
                    closing = updates["injury_case_status"] == "Closed"
                except (KeyError, TypeError):
                    closing = False
                if closing:
                    updates["status"] = "Resolved"

                frappe.db.set_value("Incident Report", name, updates)
                frappe.db.commit()
                frappe.response["message"] = {"name": name, "updated": list(updates.keys())}
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("update_workplace_injury", str(e))
    frappe.response["message"] = {"error": str(e)}

# Desk-side counterpart to confirm_host_received.py — that verb is
# allow_guest (keyed by company+badge_number, reached anonymously via the QR
# code) so it deliberately never trusts an appointment name from an
# unauthenticated caller. This one is for the "Confirm Receipt" button added
# to the Appointment form (see the matching client script) for hosts who are
# already logged into the desk and looking at the record directly, without
# needing to scan the physical badge.
try:
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    name = ""
    try:
        name = str(data["name"] or "").strip()
    except (KeyError, TypeError):
        name = ""

    if not name:
        frappe.response["message"] = {"error": "name is required"}
    else:
        appt = frappe.db.get_value(
            "Appointment",
            name,
            ["name", "custom_host_received_time", "custom_visitor_badge"],
            as_dict=True,
        )
        if not appt:
            frappe.response["message"] = {"error": "Appointment " + name + " not found"}
        elif not appt.custom_visitor_badge:
            frappe.response["message"] = {
                "error": "No visitor badge has been issued for this visit yet"
            }
        elif appt.custom_host_received_time:
            frappe.response["message"] = {
                "already_confirmed": True,
                "confirmed_at": str(appt.custom_host_received_time),
            }
        else:
            now = frappe.utils.now_datetime()
            frappe.db.set_value("Appointment", name, "custom_host_received_time", now)
            frappe.db.commit()
            frappe.response["message"] = {
                "already_confirmed": False,
                "confirmed_at": str(now),
            }
except Exception as e:
    frappe.log_error("confirm_host_received_by_appointment", str(e))
    frappe.response["message"] = {"error": str(e)}

# Desktop-friendly counterpart to get_visitor_badge_info.py (which is the
# allow_guest, QR-scan version keyed by company+badge_number since an
# anonymous scanner doesn't have a login to resolve a company from). This one
# is for a logged-in host typing just the plain badge number printed on the
# card — no company field to fill in, since we resolve it from their own
# Employee record. Not allow_guest: a Guest caller gets rejected outright.
try:
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    badge_number_raw = ""
    try:
        badge_number_raw = str(data["badge_number"]) if data["badge_number"] is not None else ""
    except (KeyError, TypeError):
        badge_number_raw = ""

    if not badge_number_raw:
        frappe.response["message"] = {"error": "badge_number is required"}
    else:
        try:
            badge_number = int(badge_number_raw)
        except Exception:
            badge_number = None

        if badge_number is None:
            frappe.response["message"] = {"error": "badge_number must be a number"}
        else:
            current_user = frappe.session.user
            employee = frappe.db.get_value(
                "Employee", {"user_id": current_user}, ["company", "custom_farm"], as_dict=True
            )
            company = employee.company if employee else ""
            farm = employee.custom_farm if employee else ""

            if not company:
                frappe.response["message"] = {
                    "error": "No Employee record linked to this login — cannot determine your company."
                }
            else:
                badge = None
                if farm:
                    # Normal case: this host's own farm narrows it to exactly
                    # one physical badge pool.
                    badge = frappe.db.get_value(
                        "Visitor Badge",
                        {"company": company, "farm": farm, "badge_number": badge_number},
                        ["current_appointment", "status", "farm"],
                        as_dict=True,
                    )
                else:
                    # Host has a company but no specific farm on file (e.g. a
                    # group-level role) — can't narrow by farm, so look across
                    # every farm under their company for whichever matching
                    # badge number is actually assigned to someone right now.
                    candidates = frappe.db.get_all(
                        "Visitor Badge",
                        filters={"company": company, "badge_number": badge_number},
                        fields=["current_appointment", "status", "farm"],
                    )
                    for c in candidates:
                        if c.current_appointment:
                            badge = c
                            break

                if not badge or not badge.current_appointment:
                    frappe.response["message"] = {
                        "error": "Badge "
                        + str(badge_number)
                        + " ("
                        + company
                        + (" / " + farm if farm else "")
                        + ") is not currently assigned to any visitor."
                    }
                else:
                    appt = frappe.db.get_value(
                        "Appointment",
                        badge.current_appointment,
                        [
                            "name",
                            "customer_name",
                            "custom_meet_with",
                            "custom_host_received_time",
                            "customer_details",
                        ],
                        as_dict=True,
                    )
                    if not appt:
                        frappe.response["message"] = {
                            "error": "Badge "
                            + str(badge_number)
                            + " points to a visit that no longer exists."
                        }
                    else:
                        host_name = (
                            frappe.db.get_value("Employee", appt.custom_meet_with, "employee_name")
                            or appt.custom_meet_with
                            or ""
                        )
                        frappe.response["message"] = {
                            "badge_number": badge_number,
                            "company": company,
                            "farm": badge.farm or farm,
                            "visitor_name": appt.customer_name or "",
                            "host_name": host_name,
                            "purpose": appt.customer_details or "",
                            "already_confirmed": bool(appt.custom_host_received_time),
                            "confirmed_at": str(appt.custom_host_received_time)
                            if appt.custom_host_received_time
                            else None,
                        }
except Exception as e:
    frappe.log_error("get_visitor_badge_info_by_number", str(e))
    frappe.response["message"] = {"error": str(e)}

# Desktop-friendly counterpart to confirm_host_received.py — see
# get_visitor_badge_info_by_number.py for why this is a separate, non-guest
# verb keyed by badge_number only (company resolved from the logged-in
# host's own Employee record).
try:
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    badge_number_raw = ""
    try:
        badge_number_raw = str(data["badge_number"]) if data["badge_number"] is not None else ""
    except (KeyError, TypeError):
        badge_number_raw = ""

    if not badge_number_raw:
        frappe.response["message"] = {"error": "badge_number is required"}
    else:
        try:
            badge_number = int(badge_number_raw)
        except Exception:
            badge_number = None

        if badge_number is None:
            frappe.response["message"] = {"error": "badge_number must be a number"}
        else:
            current_user = frappe.session.user
            employee = frappe.db.get_value(
                "Employee", {"user_id": current_user}, ["company", "custom_farm"], as_dict=True
            )
            company = employee.company if employee else ""
            farm = employee.custom_farm if employee else ""

            if not company:
                frappe.response["message"] = {
                    "error": "No Employee record linked to this login — cannot determine your company."
                }
            else:
                current_appointment = None
                if farm:
                    current_appointment = frappe.db.get_value(
                        "Visitor Badge",
                        {"company": company, "farm": farm, "badge_number": badge_number},
                        "current_appointment",
                    )
                else:
                    candidates = frappe.db.get_all(
                        "Visitor Badge",
                        filters={"company": company, "badge_number": badge_number},
                        fields=["current_appointment"],
                    )
                    for c in candidates:
                        if c.current_appointment:
                            current_appointment = c.current_appointment
                            break

                if not current_appointment:
                    frappe.response["message"] = {
                        "error": "Badge "
                        + str(badge_number)
                        + " ("
                        + company
                        + (" / " + farm if farm else "")
                        + ") is not currently assigned to any visitor."
                    }
                else:
                    appt = frappe.db.get_value(
                        "Appointment",
                        current_appointment,
                        ["name", "custom_host_received_time"],
                        as_dict=True,
                    )
                    if not appt:
                        frappe.response["message"] = {
                            "error": "Badge "
                            + str(badge_number)
                            + " points to a visit that no longer exists."
                        }
                    elif appt.custom_host_received_time:
                        frappe.response["message"] = {
                            "already_confirmed": True,
                            "confirmed_at": str(appt.custom_host_received_time),
                        }
                    else:
                        now = frappe.utils.now_datetime()
                        frappe.db.set_value(
                            "Appointment", appt.name, "custom_host_received_time", now
                        )
                        frappe.db.commit()
                        frappe.response["message"] = {
                            "already_confirmed": False,
                            "confirmed_at": str(now),
                        }
except Exception as e:
    frappe.log_error("confirm_host_received_by_number", str(e))
    frappe.response["message"] = {"error": str(e)}

# File Patrol Report — guard files an observation/incident report, either
# tied to their current active GPS patrol tag or standalone (ad-hoc tag
# generated client-side when no patrol is currently running).
# Sandbox rules: no imports, no f-strings, no top-level return, no augmented
# assignment, bracket-access + try/except instead of .get().
try:
    raw = None
    try:
        raw = frappe.request.get_json(silent=True)
    except Exception:
        raw = None
    if raw is None:
        raw = dict(frappe.form_dict or {})

    try:
        patrol = str(raw["patrol"] or "").strip()
    except (KeyError, TypeError):
        patrol = ""

    try:
        report_type = raw["report_type"]
    except (KeyError, TypeError):
        report_type = None

    try:
        observations = str(raw["observations"] or "").strip()
    except (KeyError, TypeError):
        observations = ""

    if not patrol:
        frappe.response["message"] = {"error": "Missing patrol tag"}
    elif report_type not in ["Routine", "Incident"]:
        frappe.response["message"] = {"error": "report_type must be Routine or Incident"}
    elif not observations:
        frappe.response["message"] = {"error": "Observations are required"}
    else:
        try:
            severity = raw["severity"]
        except (KeyError, TypeError):
            severity = None
        try:
            nature_of_incident = raw["nature_of_incident"]
        except (KeyError, TypeError):
            nature_of_incident = None
        try:
            incident_report = raw["incident_report"]
        except (KeyError, TypeError):
            incident_report = None
        try:
            farm = raw["farm"]
        except (KeyError, TypeError):
            farm = None
        try:
            started_at = raw["started_at"]
        except (KeyError, TypeError):
            started_at = None
        try:
            ended_at = raw["ended_at"]
        except (KeyError, TypeError):
            ended_at = None
        try:
            attachment_1 = raw["attachment_1"]
        except (KeyError, TypeError):
            attachment_1 = None
        try:
            attachment_2 = raw["attachment_2"]
        except (KeyError, TypeError):
            attachment_2 = None
        try:
            attachment_3 = raw["attachment_3"]
        except (KeyError, TypeError):
            attachment_3 = None
        try:
            attachment_4 = raw["attachment_4"]
        except (KeyError, TypeError):
            attachment_4 = None

        if report_type == "Incident" and not nature_of_incident:
            frappe.response["message"] = {"error": "Nature of incident is required for Incident reports"}
        elif incident_report and not frappe.db.exists("Incident Report", incident_report):
            frappe.response["message"] = {"error": "Linked incident report not found"}
        else:
            current_user = frappe.session.user

            # Same Employee -> Security Guard fallback pattern used by
            # submit_patrol_points.py / get_security_head_contact.py, but here
            # written into Patrol Report's own personel/internal_guard/
            # external_guard fields (unlike the legacy `guard` column on
            # Patrol GPS Log, these are real fields on this doctype).
            personel = None
            internal_guard = None
            external_guard = None
            resolved_farm = farm

            emp = frappe.db.get_value(
                "Employee", {"user_id": current_user}, ["name", "custom_farm"], as_dict=True
            )
            if emp:
                personel = "Internal Guard"
                internal_guard = emp["name"]
                if not resolved_farm:
                    resolved_farm = emp["custom_farm"]
            else:
                user_full = frappe.db.get_value("User", current_user, "full_name") or ""
                guard_name = None
                if user_full:
                    guard_name = frappe.db.get_value("Security Guard", {"full_name": user_full}, "name")
                if guard_name:
                    personel = "External Guard"
                    external_guard = guard_name

            # Auto-link this report to the guard's current Active shift, if
            # any — no guard input needed. Same identity used to resolve
            # personel/internal_guard/external_guard above. Wrapped in its
            # own try/except: this is a nice-to-have, not a requirement, and
            # different sites can have a differently-shaped Security Guard
            # Shift Assignment doctype (or none at all) — a schema mismatch
            # here must never abort the whole filing.
            resolved_shift = None
            try:
                if internal_guard:
                    resolved_shift = frappe.db.get_value(
                        "Security Guard Shift Assignment",
                        {"internal_guard": internal_guard, "status": "Active"},
                        "name",
                    )
                elif external_guard:
                    resolved_shift = frappe.db.get_value(
                        "Security Guard Shift Assignment",
                        {"external_guard": external_guard, "status": "Active"},
                        "name",
                    )
            except Exception:
                resolved_shift = None

            points_logged = frappe.db.count("Patrol GPS Log", {"patrol": patrol})

            # `patrol` is a UNIQUE field on this doctype — one report per patrol
            # tag. Treat a resubmit for the same tag as an edit (idempotent),
            # not a hard failure — a guard may re-tap after a typo, or amend
            # their observations before a supervisor reviews it.
            existing_name = frappe.db.exists("Patrol Report", {"patrol": patrol})
            if existing_name:
                report = frappe.get_doc("Patrol Report", existing_name)
            else:
                report = frappe.new_doc("Patrol Report")
                report.patrol = patrol

            report.report_type = report_type
            report.farm = resolved_farm
            report.personel = personel
            report.internal_guard = internal_guard
            report.external_guard = external_guard
            report.shift_assignment = resolved_shift
            report.started_at = started_at
            report.ended_at = ended_at
            report.points_logged = points_logged
            report.filed_at = frappe.utils.now()
            report.observations = observations
            if report_type == "Incident":
                report.severity = severity if severity else "Medium"
                report.nature_of_incident = nature_of_incident
                report.incident_report = incident_report
            else:
                report.severity = None
                report.nature_of_incident = None
                report.incident_report = None
            report.attachment_1 = attachment_1
            report.attachment_2 = attachment_2
            report.attachment_3 = attachment_3
            report.attachment_4 = attachment_4
            report.flags.ignore_links = True
            if existing_name:
                report.save(ignore_permissions=True)
            else:
                report.status = "Submitted"
                report.insert(ignore_permissions=True)
            frappe.db.commit()

            frappe.response["message"] = {
                "name": report.name,
                "patrol": report.patrol,
                "report_type": report.report_type,
                "status": report.status,
                "filed_at": str(report.filed_at),
                "points_logged": report.points_logged,
                "updated": True if existing_name else False,
            }
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("file_patrol_report", str(e))
    frappe.response["message"] = {"error": str(e)}

# Check In Shift — mobile check-in for External (contractor) guards only.
# Internal (Employee) guards have Attendance records that already carry
# their own check-in signal; External guards have no Employee record at
# all, so there's no Attendance path for them — this is the substitute.
#
# Writes only `checked_in`, never `status` — status stays purely
# clock-derived by security_guard_shift_assignment.py's own controller
# (validate() + the hourly refresh_shift_statuses job). Using
# frappe.db.set_value rather than doc.save() to avoid re-running validate()
# (which includes the overlap check) on a field that has nothing to do
# with scheduling.
try:
    current_user = frappe.session.user

    external_guard = None
    is_internal = False

    emp = frappe.db.get_value("Employee", {"user_id": current_user}, "name")
    if emp:
        is_internal = True
    else:
        user_full = frappe.db.get_value("User", current_user, "full_name") or ""
        if user_full:
            external_guard = frappe.db.get_value("Security Guard", {"full_name": user_full}, "name")

    if is_internal:
        frappe.response["message"] = {
            "error": "Employee guards check in via attendance, not the app"
        }
    elif not external_guard:
        frappe.response["message"] = {"error": "Could not resolve your guard identity"}
    else:
        shift_name = frappe.db.get_value(
            "Security Guard Shift Assignment",
            {"external_guard": external_guard, "status": ["in", ["Scheduled", "Active"]]},
            "name",
        )
        if not shift_name:
            frappe.response["message"] = {"error": "No scheduled or active shift found to check in to"}
        else:
            frappe.db.set_value(
                "Security Guard Shift Assignment", shift_name, "checked_in", 1, update_modified=True
            )
            frappe.db.commit()
            frappe.response["message"] = {"name": shift_name, "checked_in": 1}
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("check_in_shift", str(e))
    frappe.response["message"] = {"error": str(e)}

# Report Asset Missing — a guard can't scan a QR sticker that's gone with
# the asset it was on, so this is a separate path from scan_asset: the
# guard picks a known asset (from my_assets_at_farm) and confirms it's not
# where it should be. Requires the asset to already exist — nothing to
# compare a "missing" report against for a code nobody has ever scanned.
try:
    raw = None
    try:
        raw = frappe.request.get_json(silent=True)
    except Exception:
        raw = None
    if raw is None:
        raw = dict(frappe.form_dict or {})

    try:
        asset_code = str(raw["asset_code"] or "").strip()
    except (KeyError, TypeError):
        asset_code = ""
    try:
        latitude = raw["latitude"]
    except (KeyError, TypeError):
        latitude = None
    try:
        longitude = raw["longitude"]
    except (KeyError, TypeError):
        longitude = None
    try:
        accuracy = raw["accuracy"]
    except (KeyError, TypeError):
        accuracy = None
    try:
        remarks = raw["remarks"]
    except (KeyError, TypeError):
        remarks = None

    if not asset_code:
        frappe.response["message"] = {"error": "asset_code is required"}
    elif not frappe.db.exists("Security Asset", asset_code):
        frappe.response["message"] = {"error": "Unknown asset — it must be scanned as Found at least once first"}
    else:
        current_user = frappe.session.user

        personel = None
        internal_guard = None
        external_guard = None
        resolved_farm = None

        emp = frappe.db.get_value("Employee", {"user_id": current_user}, ["name", "custom_farm"], as_dict=True)
        if emp:
            personel = "Internal Guard"
            internal_guard = emp["name"]
            resolved_farm = emp["custom_farm"]
        else:
            user_full = frappe.db.get_value("User", current_user, "full_name") or ""
            guard_name = None
            if user_full:
                guard_name = frappe.db.get_value("Security Guard", {"full_name": user_full}, "name")
            if guard_name:
                personel = "External Guard"
                external_guard = guard_name
                resolved_farm = frappe.db.get_value("Security Guard", guard_name, "farm")

        log = frappe.new_doc("Asset Scan Log")
        log.asset = asset_code
        log.status = "Missing"
        log.personel = personel
        log.internal_guard = internal_guard
        log.external_guard = external_guard
        log.farm = resolved_farm
        if latitude:
            log.latitude = str(latitude)
        if longitude:
            log.longitude = str(longitude)
        if accuracy:
            log.gps_accuracy = str(accuracy)
        log.remarks = remarks
        log.scanned_at = frappe.utils.now()
        log.flags.ignore_links = True
        log.insert(ignore_permissions=True)

        guard_display = internal_guard if internal_guard else external_guard
        frappe.db.set_value(
            "Security Asset",
            asset_code,
            {
                "last_status": "Missing",
                "last_missing_reported_at": log.scanned_at,
                "last_reported_by": guard_display,
            },
            update_modified=False,
        )
        frappe.db.commit()

        frappe.response["message"] = {"asset_code": asset_code, "status": "Missing", "reported_at": str(log.scanned_at)}
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("report_asset_missing", str(e))
    frappe.response["message"] = {"error": str(e)}

# My Assets At Farm — feeds the "report missing" picker: known Security
# Assets at the calling guard's own farm, most recently seen first.
try:
    current_user = frappe.session.user

    resolved_farm = None
    emp = frappe.db.get_value("Employee", {"user_id": current_user}, "custom_farm")
    if emp:
        resolved_farm = emp
    else:
        user_full = frappe.db.get_value("User", current_user, "full_name") or ""
        guard_name = None
        if user_full:
            guard_name = frappe.db.get_value("Security Guard", {"full_name": user_full}, "name")
        if guard_name:
            resolved_farm = frappe.db.get_value("Security Guard", guard_name, "farm")

    if not resolved_farm:
        frappe.response["message"] = {"assets": []}
    else:
        rows = frappe.db.sql(
            """
            SELECT asset_code, asset_name, category, last_status, last_seen_at, last_missing_reported_at
            FROM `tabSecurity Asset`
            WHERE farm = %s
            ORDER BY COALESCE(last_seen_at, '1970-01-01') DESC
            LIMIT 200
            """,
            (resolved_farm,),
            as_dict=True,
        )
        assets = []
        for r in rows:
            assets.append(
                {
                    "asset_code": r["asset_code"],
                    "asset_name": r["asset_name"],
                    "category": r["category"],
                    "last_status": r["last_status"],
                    "last_seen_at": str(r["last_seen_at"]) if r["last_seen_at"] else None,
                    "last_missing_reported_at": str(r["last_missing_reported_at"]) if r["last_missing_reported_at"] else None,
                }
            )
        frappe.response["message"] = {"assets": assets}
except Exception as e:
    frappe.log_error("my_assets_at_farm", str(e))
    frappe.response["message"] = {"error": str(e)}

# Get Patrol Report — single-record fetch with an ownership check, same
# hierarchy as get_incident_report.py: System Manager sees everything, the
# filer always sees their own, a Security Head sees whatever their own
# User Permission grants, anyone else only their own company/farm.
#
# Patrol Report has no direct `company` field (only `farm`), so a
# Company-level grant is checked by resolving the report's farm's own
# company via the Farm doctype, not a column on Patrol Report itself.
try:
    data = {}
    try:
        data = frappe.request.get_json(silent=True) or {}
    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    name = ""
    try:
        name = str(data["name"] or "").strip()
    except (KeyError, TypeError):
        name = ""

    if not name:
        frappe.response["message"] = {"error": "name is required"}
    else:
        r = frappe.db.get_value(
            "Patrol Report",
            name,
            [
                "name",
                "patrol",
                "report_type",
                "farm",
                "personel",
                "internal_guard",
                "external_guard",
                "shift_assignment",
                "started_at",
                "ended_at",
                "points_logged",
                "filed_at",
                "observations",
                "severity",
                "nature_of_incident",
                "incident_report",
                "attachment_1",
                "attachment_2",
                "attachment_3",
                "attachment_4",
                "status",
                "reviewed_by",
                "reviewed_on",
                "supervisor_remarks",
                "owner",
            ],
            as_dict=True,
        )
        if not r:
            frappe.response["message"] = {"error": "Patrol Report " + name + " not found"}
        else:
            current_user = frappe.session.user
            role_rows = frappe.db.sql(
                "SELECT role FROM `tabHas Role` WHERE parent = %s", (current_user,)
            )
            roles = []
            for row in role_rows:
                if row and row[0]:
                    roles.append(row[0])

            is_system_manager = "System Manager" in roles
            is_security_head = "Security Head" in roles

            allowed = is_system_manager or r.owner == current_user

            if not allowed:
                report_company = None
                if r.farm:
                    report_company = frappe.db.get_value("Farm", r.farm, "company")

                scope_companies = []
                scope_farms = []
                if is_security_head:
                    perm_rows = frappe.db.sql(
                        "SELECT allow, for_value FROM `tabUser Permission` "
                        "WHERE user = %s AND allow IN ('Company', 'Farm')",
                        (current_user,),
                        as_dict=True,
                    )
                    for p in perm_rows:
                        if p.allow == "Company" and p.for_value:
                            scope_companies.append(p.for_value)
                        elif p.allow == "Farm" and p.for_value:
                            scope_farms.append(p.for_value)
                else:
                    employee = frappe.db.get_value(
                        "Employee", {"user_id": current_user}, ["company", "custom_farm"], as_dict=True
                    )
                    if employee:
                        if employee.company:
                            scope_companies.append(employee.company)
                        if employee.custom_farm:
                            scope_farms.append(employee.custom_farm)
                    else:
                        user_full = frappe.db.get_value("User", current_user, "full_name") or ""
                        if user_full:
                            guard = frappe.db.get_value(
                                "Security Guard", {"full_name": user_full}, ["company", "farm"], as_dict=True
                            )
                            if guard:
                                if guard.company:
                                    scope_companies.append(guard.company)
                                if guard.farm:
                                    scope_farms.append(guard.farm)

                if report_company and report_company in scope_companies:
                    allowed = True
                elif r.farm and r.farm in scope_farms:
                    allowed = True

            if not allowed:
                frappe.response["message"] = {"error": "You do not have access to this patrol report"}
            else:
                frappe.response["message"] = {
                    "name": r.name,
                    "patrol": r.patrol or "",
                    "report_type": r.report_type or "",
                    "farm": r.farm or "",
                    "personel": r.personel or "",
                    "internal_guard": r.internal_guard or "",
                    "external_guard": r.external_guard or "",
                    "shift_assignment": r.shift_assignment or "",
                    "started_at": str(r.started_at) if r.started_at else "",
                    "ended_at": str(r.ended_at) if r.ended_at else "",
                    "points_logged": r.points_logged or 0,
                    "filed_at": str(r.filed_at) if r.filed_at else "",
                    "observations": r.observations or "",
                    "severity": r.severity or "",
                    "nature_of_incident": r.nature_of_incident or "",
                    "incident_report": r.incident_report or "",
                    "attachment_1": r.attachment_1 or "",
                    "attachment_2": r.attachment_2 or "",
                    "attachment_3": r.attachment_3 or "",
                    "attachment_4": r.attachment_4 or "",
                    "status": r.status or "",
                    "reviewed_by": r.reviewed_by or "",
                    "reviewed_on": str(r.reviewed_on) if r.reviewed_on else "",
                    "supervisor_remarks": r.supervisor_remarks or "",
                }
except Exception as e:
    frappe.log_error("get_patrol_report", str(e))
