        # never actually populated. Only enforce Link-style validation when
        # that master data actually exists — otherwise trust the Select
        # field's own built-in option list (Frappe rejects an invalid Select
        # value on insert regardless).
        category_master_in_use = frappe.db.count("Incident Category") > 0
        cat_ok = True
        if category_master_in_use:
            cat_ok = bool(frappe.db.get_value("Incident Category", nature_of_incident, "name"))

        if not cat_ok:
            frappe.response["message"] = {
                "error": "Incident Category '" + nature_of_incident + "' does not exist"
            }
        else:
            user = frappe.session.user
            full_name = frappe.db.get_value("User", user, "full_name") or user
            now = frappe.utils.now_datetime()

            doc = frappe.new_doc("Incident Report")
            doc.incident_datetime = incident_datetime
            doc.location = location
            doc.nature_of_incident = nature_of_incident
            doc.severity = severity
            doc.description = description
            doc.reported_by = user
            doc.reporter_name = full_name
            doc.reported_datetime = now
            doc.status = "Open"
            if attachment_1:
                doc.attachment_1 = attachment_1
            if attachment_2:
                doc.attachment_2 = attachment_2
            if attachment_3:
                doc.attachment_3 = attachment_3
            if attachment_4:
                doc.attachment_4 = attachment_4

            doshs_deadline = ""
            if nature_of_incident == "Workplace Injury":
                is_fatal = s("is_fatal") in ("1", "true", "True")
                doc.is_fatal = 1 if is_fatal else 0
                doc.injury_case_status = "Reported"

                activity_at_time_of_injury = s("activity_at_time_of_injury")
                if activity_at_time_of_injury:
                    doc.activity_at_time_of_injury = activity_at_time_of_injury
                body_part_affected = s("body_part_affected")
                if body_part_affected:
                    doc.body_part_affected = body_part_affected
                nature_of_injury = s("nature_of_injury")
                if nature_of_injury:
                    doc.nature_of_injury = nature_of_injury
                injury_current_location = s("injury_current_location")
                if injury_current_location:
                    doc.injury_current_location = injury_current_location

                try:
                    incident_dt = frappe.utils.get_datetime(incident_datetime)
                    days = 2 if is_fatal else 7
                    doshs_deadline = str(frappe.utils.add_days(incident_dt, days).date())
                    doc.doshs_deadline = doshs_deadline
                except Exception:
                    doshs_deadline = ""

            doc.insert(ignore_permissions=True)
            frappe.db.commit()
            frappe.response["message"] = {
                "name": doc.name,
                "incident_datetime": incident_datetime,
                "location": location,
                "nature_of_incident": nature_of_incident,
                "severity": severity,
                "description": description,
                "reported_by": user,
                "reporter_name": full_name,
                "status": "Open",
                "doshs_deadline": doshs_deadline,
            }
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("create_incident", str(e))
    frappe.response["message"] = {"error": str(e)}

# Returns all Incident Report rows for the gate dashboard, optionally filtered
# by an inclusive incident_datetime date range.
#
# Request payload (all optional):
#   { "from_date": "YYYY-MM-DD", "to_date": "YYYY-MM-DD", "limit": <int> }
#
# Access scoping: Incident Report has no direct company/farm field, so the
# scope is inferred from whoever reported it (Employee.user_id = reported_by).
# System Manager sees everything; a Security Head sees whatever their own
# User Permission grants (Company and/or Farm); anyone else (a regular gate
# guard) is scoped to their own company/farm only.
#
# Notes (safe-exec quirks):
#   - frappe.form_dict gets request args; we use bracket access in try/except
#     because .get(...) is intercepted as a key lookup, not a method.
#   - SQL is parameterised — never interpolate user input.
#   - Default limit is 200 rows so the picker stays responsive; raise via the
#     limit param if you genuinely need more.
try:
    form = frappe.form_dict

    from_date = ""
    try:
        from_date = form["from_date"] or ""
    except (KeyError, TypeError):
        from_date = ""

    to_date = ""
    try:
        to_date = form["to_date"] or ""
    except (KeyError, TypeError):
        to_date = ""

    limit = 200
    try:
        raw_limit = form["limit"]
        if raw_limit:
            limit = int(raw_limit)
    except (KeyError, TypeError, ValueError):
        limit = 200
    if limit < 1:
        limit = 1
    if limit > 1000:
        limit = 1000

    current_user = frappe.session.user
    role_rows = frappe.db.sql(
        "SELECT role FROM `tabHas Role` WHERE parent = %s", (current_user,)
    )
    roles = []
    for row in role_rows:
        if row and row[0]:
            roles.append(row[0])

    is_system_manager = "System Manager" in roles
    is_security_head = "Security Head" in roles

    scope_companies = []
    scope_farms = []

    if not is_system_manager:
        if is_security_head:
            perm_rows = frappe.db.sql(
                "SELECT allow, for_value FROM `tabUser Permission` "
                "WHERE user = %s AND allow IN ('Company', 'Farm')",
                (current_user,),
                as_dict=True,
            )
            for p in perm_rows:
                if p.allow == "Company" and p.for_value:
                    scope_companies.append(p.for_value)
                elif p.allow == "Farm" and p.for_value:
                    scope_farms.append(p.for_value)
        else:
            employee = frappe.db.get_value(
                "Employee", {"user_id": current_user}, ["company", "custom_farm"], as_dict=True
            )
            if employee:
                if employee.company:
                    scope_companies.append(employee.company)
                if employee.custom_farm:
                    scope_farms.append(employee.custom_farm)
            else:
                user_full = frappe.db.get_value("User", current_user, "full_name") or ""
                if user_full:
                    guard = frappe.db.get_value(
                        "Security Guard", {"full_name": user_full}, ["company", "farm"], as_dict=True
                    )
                    if guard:
                        if guard.company:
                            scope_companies.append(guard.company)
                        if guard.farm:
                            scope_farms.append(guard.farm)

    where_parts = ["1=1"]
    params = {}
    if from_date:
        where_parts.append("DATE(i.incident_datetime) >= %(from_date)s")
        params["from_date"] = from_date
    if to_date:
        where_parts.append("DATE(i.incident_datetime) <= %(to_date)s")
        params["to_date"] = to_date

    if not is_system_manager:
        conditions = []
        if scope_companies:
            placeholders = ", ".join(["%(c" + str(idx) + ")s" for idx in range(len(scope_companies))])
            conditions.append("e.company IN (" + placeholders + ")")
            for idx in range(len(scope_companies)):
                params["c" + str(idx)] = scope_companies[idx]
        if scope_farms:
            placeholders = ", ".join(["%(f" + str(idx) + ")s" for idx in range(len(scope_farms))])
            conditions.append("e.custom_farm IN (" + placeholders + ")")
            for idx in range(len(scope_farms)):
                params["f" + str(idx)] = scope_farms[idx]
        if conditions:
            where_parts.append("(" + " OR ".join(conditions) + ")")
        else:
            # No resolvable company/farm for this user at all — show nothing
            # rather than silently falling through to "everything".
            where_parts.append("1=0")

    params["row_limit"] = limit

    where_clause = " AND ".join(where_parts)
    sql = (
        "SELECT i.name, i.incident_datetime, i.location, i.nature_of_incident, i.severity, "
        "i.description, i.status, i.reported_datetime, i.reported_by "
        "FROM `tabIncident Report` i "
        "LEFT JOIN `tabEmployee` e ON e.user_id = i.reported_by "
        "WHERE " + where_clause + " "
        "ORDER BY i.incident_datetime DESC "
        "LIMIT %(row_limit)s"
    )

    rows = frappe.db.sql(sql, params, as_dict=True)
    out = []
    for r in rows:
        out.append(
            {
                "name": r.name,
                "incident_datetime": str(r.incident_datetime) if r.incident_datetime else "",
                "location": r.location or "",
                "nature_of_incident": r.nature_of_incident or "",
                "severity": r.severity or "",
                "description": r.description or "",
                "status": r.status or "",
                "reported_datetime": str(r.reported_datetime) if r.reported_datetime else "",
                "reported_by": r.reported_by or "",
            }
        )
    frappe.response["message"] = out
except Exception as e:
    frappe.log_error("list_incidents", str(e))
    frappe.response["message"] = {"error": str(e)}

try:
    # Body parsing — accept JSON list, JSON object, or form-encoded.
    raw = None
    try:
        raw = frappe.request.get_json(silent=True)
    except Exception:
        raw = None

    # Safe-exec gotchas worked around:
    #   - `.get(...)` on dicts is intercepted as a key lookup, returns None.
    #   - Attribute access on plain dicts silently returns None.
    #   - Duck-typing via try/except AttributeError doesn't fire on lists.
    # So: probe via integer indexing for list-ness, then read entries via
    # bracket access wrapped in try/except KeyError.
    data_list = []
    if raw is not None:
        is_list = False
        try:
            probe = raw[0]
            is_list = True
        except Exception:
            is_list = False
        if is_list:
            data_list = raw
        else:
            data_list = [raw]
    if not data_list:
        f = dict(frappe.form_dict or {})
        if f:
            data_list = [f]

    if not data_list:
        frappe.response["message"] = [
            {"status": "error", "message": "GPS data missing"}
        ]
    else:
        results = []
        any_success = False
        current_user = frappe.session.user

        # Resolve who is patrolling. Guards live in one of two doctypes: internal
        # guards are Employees, external guards are Security Guard records.
        # Order: Employee by user_id -> Security Guard by user -> Security Guard
        # by full name (legacy, for guards not yet given a User link) -> raw
        # user identity.
        user_full = ""
        try:
            user_full = frappe.db.get_value("User", current_user, "full_name") or ""
        except Exception:
            user_full = ""

        resolved_type = ""
        resolved_guard = ""
        emp = frappe.db.get_value("Employee", {"user_id": current_user}, "name")
        if emp:
            resolved_type = "Employee"
            resolved_guard = emp
        else:
            sg = frappe.db.get_value("Security Guard", {"user": current_user}, "name")
            if not sg and user_full:
                # Name matching is fragile — duplicates collide and a renamed
                # user silently detaches. Kept only until every Security Guard
                # has its User link populated.
                sg = frappe.db.get_value("Security Guard", {"full_name": user_full}, "name")
            if sg:
                resolved_type = "Security Guard"
                resolved_guard = sg

        if not resolved_guard:
            resolved_guard = user_full or current_user

        # Which farm this guard is patrolling right now - their currently
        # Active shift assignment, same source the missed-check-in/geofence
        # scheduled task already trusts for this. Resolved once per batch
        # (not per point) since every point in one submission belongs to the
        # same ongoing shift.
        #
        # Falls back to the guard's own farm on their Employee/Security
        # Guard master record when no Active shift assignment matches -
        # this is NOT a rare edge case for external guards: Security Guard
        # Shift Assignment is only ever created with internal_guard set in
        # practice (external_guard is never populated on any assignment on
        # kaitetv16), so external guards - most of the actual patrol
        # traffic - got a permanently blank farm on every single GPS point
        # without this fallback, silently breaking the Patrol Map's farm
        # filter (a blank farm never matches a real filter value, so
        # filtering by farm made almost every point disappear). Only when
        # BOTH sources come up empty (no shift assignment AND no farm on
        # the guard's own record) is farm left blank - still honest, just
        # no longer the default outcome for a whole guard type.
        resolved_farm = ""
        try:
            if resolved_type == "Employee":
                resolved_farm = frappe.db.get_value(
                    "Security Guard Shift Assignment",
                    {"internal_guard": resolved_guard, "status": "Active"},
                    "farm",
                ) or ""
                if not resolved_farm:
                    resolved_farm = frappe.db.get_value(
                        "Employee", resolved_guard, "custom_farm"
                    ) or ""
            elif resolved_type == "Security Guard":
                resolved_farm = frappe.db.get_value(
                    "Security Guard Shift Assignment",
                    {"external_guard": resolved_guard, "status": "Active"},
                    "farm",
                ) or ""
                if not resolved_farm:
                    resolved_farm = frappe.db.get_value(
                        "Security Guard", resolved_guard, "farm"
                    ) or ""
        except Exception:
            resolved_farm = ""

        for entry in data_list:
            try:
                # Use a fresh defaulted lookup that doesn't rely on .get().
                patrol_tag = ""
                try:
                    patrol_tag = str(entry["patrol_tag"] or "").strip()
                except (KeyError, TypeError):
                    pass
                if not patrol_tag:
                    try:
                        patrol_tag = str(entry["patrol"] or "").strip()
                    except (KeyError, TypeError):
                        pass

                guard_code = ""
                try:
                    guard_code = str(entry["guard"] or "").strip()
                except (KeyError, TypeError):
                    pass

                latitude = None
                try:
                    latitude = entry["latitude"]
                except (KeyError, TypeError):
                    latitude = None
                longitude = None
                try:
                    longitude = entry["longitude"]
                except (KeyError, TypeError):
                    longitude = None
                accuracy = None
                try:
                    accuracy = entry["accuracy"]
                except (KeyError, TypeError):
                    accuracy = None
                captured_at = None
                try:
                    captured_at = entry["captured_at"]
                except (KeyError, TypeError):
                    captured_at = None

                if not patrol_tag:
                    results.append(
                        {"status": "error", "message": "patrol_tag is required"}
                    )
                    continue

                if not latitude or not longitude or not captured_at:
                    results.append(
                        {
                            "status": "error",
                            "message": "latitude, longitude and captured_at are required",
                            "patrol_tag": patrol_tag,
                        }
                    )
                    continue

                existing = frappe.db.get_value(
                    "Patrol GPS Log",
                    {"patrol": patrol_tag, "captured_at": captured_at},
                    "name",
                )
                if existing:
                    results.append(
                        {
                            "status": "success",
                            "message": "Duplicate - already synced",
                            "name": existing,
                            "patrol_tag": patrol_tag,
                            "duplicate": True,
                        }
                    )
                    continue

                guard = resolved_guard
                if not guard:
                    guard = guard_code

                log = frappe.new_doc("Patrol GPS Log")
                log.patrol = patrol_tag
                if resolved_farm:
                    log.farm = resolved_farm
                if resolved_type == "Employee":
                    log.personel = "Internal Guard"
                    log.internal_guard = guard
                elif resolved_type == "Security Guard":
                    log.personel = "External Guard"
                    log.external_guard = guard
                log.captured_at = captured_at
                log.latitude = str(latitude)
                log.longitude = str(longitude)
                if accuracy:
                    log.gps_accuracy = str(accuracy)
                # guard now holds a User full name / email, not an Employee — skip
                # link validation so users without an Employee record can submit.
                log.flags.ignore_links = True
                log.insert(ignore_permissions=True)

                any_success = True
                results.append(
                    {
                        "status": "success",
                        "name": log.name,
                        "patrol_tag": patrol_tag,
                        "captured_at": str(captured_at),
                    }
                )
            except Exception as row_err:
                frappe.log_error("submit_patrol_points row", str(row_err))
                results.append({"status": "error", "message": str(row_err)})

        if any_success:
            frappe.db.commit()
        else:
            frappe.db.rollback()

        frappe.response["message"] = results
except Exception as e:
    frappe.db.rollback()
    frappe.log_error("submit_patrol_points", str(e))
    frappe.response["message"] = [{"status": "error", "message": str(e)}]

try:
