        else:
            first_task = frappe.db.sql(
                """
                SELECT activity_type, description, task
                FROM `tabTimesheet Detail`
                WHERE parent = %s
                ORDER BY idx ASC
                LIMIT 1
                """,
                (ticket,),
                as_dict=True,
            )
            activity = "Transport"
