    except Exception:
        data = {}
    if not data:
        data = dict(frappe.form_dict or {})

    def s(key):
        try:
            v = data[key]
            if v is None:
                return ""
            return str(v).strip()
        except (KeyError, TypeError):
            return ""

    customer = s("customer")
    person_name = s("person_name")
    id_number = s("id_number")
    host = s("host")
    scheduled_time = s("scheduled_time")
    purpose = s("purpose")

    if not customer:
