    elif not host:
        frappe.response["message"] = {"error": "host is required"}
    elif not scheduled_time:
        frappe.response["message"] = {"error": "scheduled_time is required"}
    else:
        customer_doc = frappe.db.get_value(
            "Customer", customer, ["name", "customer_name", "mobile_no", "email_id"], as_dict=True
        )
        if not customer_doc:
            frappe.response["message"] = {"error": "Customer " + customer + " not found"}
        else:
            host_ok = frappe.db.get_value("Employee", host, "name")
            if not host_ok:
                frappe.response["message"] = {"error": "Host " + host + " not found"}
            else:
                # Phone/email are always sourced from the linked Customer's own
                # contact details, never typed by the guard/host booking this -
                # the only thing captured about the actual person being sent is
                # their name and ID number.
                doc = frappe.new_doc("Appointment")
                doc.flags.ignore_mandatory = True
                doc.customer_name = person_name
                doc.custom_id_number = id_number
                doc.custom_customer = customer_doc.name
                doc.customer_phone_number = customer_doc.mobile_no or ""
                doc.customer_email = customer_doc.email_id or ""
                doc.custom_meet_with = host
                doc.scheduled_time = scheduled_time
                doc.customer_details = purpose
                doc.custom_visitor_type = "Customer"
                doc.status = "Open"
                # Deliberately NOT setting workflow_state here - a new
                # Appointment always inserts into the workflow's first state
                # (Open), and the real Workflow now enforces that a
                # transition can only move to a state that's actually
                # reachable via a named action, not an arbitrary direct
                # assignment. "Open -> Notify Host -> Pending Host Review"
                # IS a real transition, but apply_workflow() can't be
                # imported inside the safe-exec sandbox - so, same as
                # Check In Visitor / Check Out Visitor, the move to Pending
                # Host Review happens via a plain frappe.db.set_value
                # bypass in a second step below, after the doc already
                # exists validly in its own initial state.
                doc.insert(ignore_permissions=True)
                frappe.db.set_value("Appointment", doc.name, "workflow_state", "Pending Host Review")
                frappe.db.commit()
                frappe.response["message"] = {
                    "name": doc.name,
                    "customer_name": doc.customer_name,
                    "custom_customer": doc.custom_customer,
                    "host_id": host,
                    "scheduled_time": str(doc.scheduled_time),
